import { Badge } from "@b2mash/ui/badge";

/**
 * "Brought forward — take-on" (Phase 93 658A, §17.4.3, X3): marks a fee note the previous system
 * issued and the take-on brought into Kazi. Nothing when the fee note was generated by Kazi.
 */
export function BroughtForwardBadge({ takeOnBatchId }: { takeOnBatchId?: string | null }) {
  if (!takeOnBatchId) return null;
  return (
    <Badge variant="neutral" data-testid="fee-note-takeon-badge">
      Brought forward — take-on
    </Badge>
  );
}
